export const PROMOTION_IDS = Object.keys(PROMOTIONS)

// The two promotions of a base class, in data order.
export function promotionsFor(classId) {
  return PROMOTION_IDS.filter((id) => PROMOTIONS[id].base === classId).map((id) => PROMOTIONS[id])
}

export function promotionById(id) {
  return PROMOTIONS[id] || null
}
